\begin{corollary}\label{cor:ordinary}
Every finite nonempty simple graph $G$ satisfies $\chi(G)\le C h(G)$,
with the constant $C$ in Theorem~\ref{thm:main}.
\end{corollary}

\begin{theorem}[Fractional minor bound]\label{thm:fractional}
Every graph $P$ satisfies $f(P)\le4h(P)$.
\end{theorem}

\begin{theorem}[Ordinary-chromatic connectivity extraction]
\label{thm:ordinary-extraction}
If $k\ge1$ is an integer and $\chi(P)\ge7k$, then $P$ has a
$k$-connected subgraph $J$ with $\chi(J)\ge\chi(P)-6k$.
\end{theorem}

\begin{theorem}[Grouping terminals]\label{thm:grouping}
There is an absolute integer $\gamma\ge1$ such that the following holds.
In a $\gamma m$-connected graph, every partition of $m\ge1$ distinct
terminals into nonempty groups can be realized by pairwise disjoint
connected vertex sets, one containing each group.
\end{theorem}

\begin{proposition}\label{prop:small-list}
There are an absolute positive integer $L$ and an absolute integer $t_0$
such that, for every integer $t\ge t_0$ and every graph $G$,
\[
 h(G)<t,\qquad |V(G)|\le t^{11/10}
 \quad\Longrightarrow\quad \ell(G)\le Lt.
\]
\end{proposition}

\begin{lemma}\label{small:fixed-region}
Suppose that every outcome of the experiment
\eqref{small:remainder} having positive probability satisfies
$f(P[W])>r/2$. Then there is a fixed induced $k$-connected subgraph
$H\subseteq P$ such that
\begin{equation}\label{small:region-expectation}
 \mathbb E f(H[W\cap V(H)])>r/4.
\end{equation}
The subgraph $H$ is chosen before any fresh copies of the experiment
are sampled.
\end{lemma}

\begin{lemma}\label{small:private}
With failure probability at most $4q(q-1)p+o(1)$, every $H[T_i]$ has
fractional chromatic number greater than $r/8$, and hence contains a
$K_{2x}$ model.
\end{lemma}

\begin{lemma}\label{small:complement}
With probability $1-o(1)$, every vertex of $H$ has at least $k/2$
neighbors in $H-U$, and $H-U$ is $\lfloor k/32\rfloor$-connected.
\end{lemma}

\begin{lemma}\label{list:constrained-coloring}
Let $k\ge1$ and $m\ge0$ be integers. Suppose every induced $k$-connected
subgraph of $P$ has list chromatic number at most $m$. Give each vertex $v$
a list $\mathcal L(v)$ of size at least $m+6k$. Suppose also that:
\begin{enumerate}[label=\textup{(\roman*)}]
\item a set $A\subseteq V(P)$ has a proper list precoloring $\varphi$;
\item for each $v\notin A$, a finite set $B_v$ of forbidden colors is
specified, with $|B_v|<k$;
\item the constraints satisfy
\begin{equation}\label{list:eq-budget}
k|A|+\sum_{v\notin A}|B_v|\le2k^2.
\end{equation}
\end{enumerate}
Then $P$ has a proper $\mathcal L$-coloring extending $\varphi$ and avoiding
$B_v$ at every $v\notin A$.
\end{lemma}

\begin{lemma}\label{lem:incidence}
There is an absolute positive integer \(B_*\) such that, for all sufficiently
large integers \(t\), every graph \(P\) with \(h(P)<t\) and disjoint vertex
sets \(A,T\) satisfies
\begin{equation}\label{density:incidence-bound}
 \sum_{\substack{v\in T\\ |N_P(v)\cap A|\ge B_*t}}
       |N_P(v)\cap A|
 \le t^{1+2\epsilon}|A|.
\end{equation}
In particular,
\[
 \bigl|\{v\in T:|N_P(v)\cap A|\ge B_*t\}\bigr|
 \le t^{2\epsilon}|A|.
\]
\end{lemma}

\begin{lemma}\label{density:connectivity}
For every positive integer \(k\), a graph of density greater than \(2k\)
contains an induced \(k\)-connected subgraph.
\end{lemma}

\begin{lemma}[Rooting a large clique minor]\label{lem:rooting}
Let $k\ge1$.  If $P$ is $2k$-connected and $h(P)\ge4k$, then any given
$k$ distinct vertices are roots of a $K_k$ model: its bags can be indexed
by the given vertices so that each bag contains its indexing root.
\end{lemma}

\begin{lemma}[Bounds from unpaired path minimization]
\label{lem:path-minimization}
Let $A,B$ be disjoint vertex sets in a graph $P$.  Suppose that a system
of one of the two types above is feasible, and choose one of minimum
total length.  Let $q$ be its number of paths and $U$ its vertex union.
Then:
\begin{enumerate}[label=(\roman*)]
\item the paths have no internal vertices in $A\cup B$;
\item each vertex of $V(P)\setminus U$ has at most three neighbors
      on any one path;
\item $P[U\setminus A]$ is $2q$-degenerate for type~\textup{(1)},
      and $P[U]$ is $2q$-degenerate for type~\textup{(2)}.
\end{enumerate}
\end{lemma}

\begin{theorem}\label{thm:recursive-woven}
There are absolute positive integers $K,Q$ such that, for every integer
$a\ge1$, every $Ka$-connected graph $P$ with $\ell(P)\ge Qa$ is
$(a,3a)$-woven.
\end{theorem}

\begin{lemma}
\label{lem:counting-lifts}
If $k$ has both integer signatures of Definition~\ref{def:integer-signatures},
then $f$ has the omission property and $\widetilde f$ has the addition
property.  Both properties persist under fixing included or excluded
elements and summing disjoint labelled pairs at occupancy one, on each
resulting full valid-degree domain.  Moreover, with $q=(p+1)^2$,
\begin{equation}
 q^{-1}f(S)\leq\widetilde f(S)\leq qf(S)
 \quad\left(S\in\mathcal A\cup\bigcup_{i\ne l}\mathcal A_{il}\right).
 \label{eq:counting-comparison}
\end{equation}
\end{lemma}

\begin{proposition}[Companion transport and simulation input]
\label{prop:counting-transport}
Suppose $f$ is positive on all $p$-subsets and has the omission property,
$\widetilde f$ is positive on that domain and has the addition property,
the weights agree on $\mathcal A$, and
\eqref{eq:counting-comparison} holds with $q\geq1$.
For good multipliers put
\begin{equation}
 C_{\rm p}=p(1+8pq^2),\qquad
 C_{\rm d}=8+32pq^3,\qquad
 K_{\rm obs}=10p^4(9C_{\rm p}+2C_{\rm d}).
 \label{eq:counting-constants}
\end{equation}
Then for every real function $g$ on $\mathcal X$,
\begin{equation}
 C\operatorname{Var}_\mu(g)\leq C_{\rm p}\mathfrak D(g),\qquad
 \operatorname{Var}_\pi(\mathcal Qg)
 \leq(9C_{\rm p}+2C_{\rm d})\frac{\mathfrak D(g)}C
 \leq K_{\rm obs}\mathcal E_P(g).
 \label{eq:counting-variance}
\end{equation}
If $\mathcal QG=G$ and an initial law satisfies $\nu\leq D\pi$
pointwise, then $m\geq1$ consecutive observations satisfy
\begin{equation}
 \mathbb E_\nu\left[
  \left(m^{-1}\sum_{t=0}^{m-1}G(S_t)-\mathbb E_\pi G\right)^2\right]
 \leq\frac{2D K_{\rm obs}}m\operatorname{Var}_\pi(G).
 \label{eq:counting-time-average}
\end{equation}
The trace on $\mathcal A$, counting every strictly positive return as
one step, is lazy and reversible with stationary law $\mu$ and inverse
spectral gap at most $2p^2C_{\rm p}\leq K_{\rm obs}$.  In particular,
\begin{equation}
 \left|\frac{P_{\rm tr}^t(x,y)}{\mu(y)}-1\right|
 \leq\mu_{\min}^{-1}\exp(-t/K_{\rm obs}).
 \label{eq:counting-trace-mixing}
\end{equation}
If a trace starts from $\nu\leq D\mu$, the expected cost of $t$ trace
steps in underlying transitions is at most $tD/\pi(\mathcal A)$;
at each deterministic trace index its law is still at most $D\mu$.
\end{proposition}

\begin{lemma}[Initialization and adjacent phases]
\label{lem:counting-initialization}
For every $p$-subset and $0\leq j<H_o$,
\begin{equation}
 \frac12\leq\frac{f_{j+1}(S)}{f_j(S)}\leq1.
 \label{eq:counting-adjacent}
\end{equation}
Thus $C_j/c_{il}(j)$ changes by a factor in $[1/2,2]$ between
consecutive phases, and $\mu_j=f_j/C_j$ on $\mathcal A$ satisfies
$\mu_j\leq2\mu_{j+1}$.  Moreover
\begin{equation}
 \min_{S\in\mathcal A}\mu_j(S)
       \geq2^{-(H_o+p+K_o)}.
 \label{eq:counting-minimum}
\end{equation}
The initial masses are exact rational numbers computable in polynomial
bit time, and $\mu_0$ can be sampled by independent uniform port counts
followed by uniform subsets of the pairs realizing those counts.
\end{lemma}

\begin{proposition}
\label{prop:counting-reference}
With probability at least $1-1/50$, this experiment does not abort,
every stored multiplier collection is good at its own phase, and
\begin{equation}
 \left|\log\frac{Y_{\rm ref}}{C_{H_o}}\right|\leq4H_o\eta.
 \label{eq:counting-reference-error}
\end{equation}
\end{proposition}

\begin{lemma}
\label{lem:counting-bits}
The implemented experiment has deterministic polynomial bounds on
oracle calls, bit operations, and output length, on every execution.
It can be coupled to the capped reference experiment so that, except
with probability at most $20J_*\xi$, all states, type counts,
multiplier updates, and cap decisions coincide, every weight evaluation
meets its tolerance, and each positive observed ratio differs from
its reference value by log error at most $4\xi$.
\end{lemma}

\begin{lemma}[Integral and point-weight bounds]\label{lem:weight-bounds}
For every block and every port argument in its box,
\begin{equation}\label{eq:integral-bounds}
 e^{-N^{50000}}\le\widetilde I_G(u)\le e^K.
\end{equation}
For the weight $h$ on the full paired slice of
Proposition~\ref{prop:port-model},
\begin{equation}\label{eq:weight-log-bound}
 |\log h(a,b)|\le N^{60000}.
\end{equation}
All rational coefficients needed to define or evaluate its factors
have polynomial encoding length in the input and in the query.
\end{lemma}

\begin{lemma}[Accuracy and guarantees for the volume lift]
\label{lem:volume-lift}
The polytope~\eqref{eq:volume-lift} has dimension $f+6m+d_0$, a
polynomial facet-encoding bound, and an exact polynomial-time strong
separation oracle. It contains a known rational ball of radius $1/32$
and has an outer ball of polynomial encoding length. Furthermore,
\begin{equation}\label{eq:volume-lift-accuracy}
 (1-\rho/10)\widetilde I_G(u)
       \le\vol(\mathcal Q)\le\widetilde I_G(u).
\end{equation}
All polynomial bounds are in the original input length, the encoding
lengths of $u$ and $\rho$, $N$, and $\rho^{-1}$, with absolute fixed exponents.
\end{lemma}

\begin{lemma}[Computable partitions and compatible orders]
\label{lem:partitions}
Each part of \(\mathcal D_i\) is contained in a superblock.
The three partitions can be found with polynomially many oracle calls
and bit operations.  Each has a generating family of at most \(n^2\)
sets satisfying its defining strict slack bound.

Fix a superblock order \(G_1,\ldots,G_g\) supplied by
Lemma~\ref{lem:generator-prefixes} for the \(s_*\)-generators.
Every prefix \(F_k=G_1\cup\cdots\cup G_k\), including the empty
and full prefixes, satisfies
\begin{equation}\label{eq:superblock-prefix-slack}
 s_*(F_k)\le N^4S.
\end{equation}
For system 1 use this order, and for system 2 use its reverse.  The
sets preceding a superblock \(G_k\) in these orders are therefore
\begin{equation}\label{eq:superblock-prefixes}
 A_{1G_k}=F_{k-1},\qquad A_{2G_k}=E\setminus F_k.
\end{equation}
\end{lemma}

\begin{lemma}[Shift averages]\label{lem:shift-average}
For \(F=Y\) and for \(F=Y^+\), every integral full or restricted
star shift with \(|l_j|\le S/N^{25}\) satisfies
\begin{equation}\label{eq:small-shift-ratio}
 e^{-N^{-8}}\le \frac{F(d(l))}{F(0)}\le e^{N^{-8}}.
\end{equation}
For \((\kappa,A_\kappa)=(\omega,A_\omega)\) or \((\psi,J)\),
on its corresponding star lattice,
\begin{equation}\label{eq:average-comparison}
 e^{-3N^{-8}}F(0)
 \le \frac{1}{A_\kappa}\sum_l\kappa(l)F(d(l))
 \le e^{3N^{-8}}F(0).
\end{equation}
The lower bound remains valid if the sum is restricted to
\(\max_j|l_j|\le S/N^{25}\).
\end{lemma}

\begin{proposition}[Expansion costs little]\label{prop:expansion}
The expanded common-base count satisfies
\begin{equation}\label{eq:expansion-comparison}
 Z\le Z^+\le e^{20N^{-8}}Z.
\end{equation}
\end{proposition}

\begin{lemma}[The expansion matroid]\label{lem:expansion-matroid}
Let $r:2^E\to\mathbb Z_{\geq0}$ be normalized, nondecreasing, and
submodular.  Replace each $j\in E$ by any finite number of labelled
copies.  Declare a set of copies independent when its occupancy vector
$z$ satisfies $z(A)\leq r(A)$ for every $A\subseteq E$.
This defines a matroid.  A set of copies with occupancy vector $v$ has
matroid rank
\begin{equation}\label{eq:expansion-rank}
 m(v)=\min_{A\subseteq E}\{r(A)+v(E\setminus A)\}.
\end{equation}
\end{lemma}

\begin{lemma}[A center for affine slacks]\label{lem:center}
Let $Q\subseteq\mathbb R^n$ be a nonempty bounded rational polytope
satisfying the hypotheses of Proposition~\ref{prop:oracle-tools}.
One can find a rational $c\in Q$, with polynomial encoding length,
such that every affine $F$ nonnegative on $Q$ satisfies
\begin{equation}\label{eq:center-slack}
 \max_{x\in Q}F(x)\leq4(n+1)F(c).
\end{equation}
The construction has polynomial oracle and bit complexity.
It also returns an affinely spanning vertex simplex of $Q$ such that
every point of $Q$ has all barycentric coordinates of absolute value
at most two with respect to that simplex.
\end{lemma}

\begin{lemma}[Derivatives after smoothing]\label{lem:smooth-derivatives}
In block count coordinates, $g=\log\widetilde I_G$ is $C^3$, is concave,
and satisfies, everywhere,
\begin{equation}\label{eq:smooth-derivative-bounds}
 |g''_{ij}|\le A_2=N^{800}/W^2,\qquad
 |g'''_{ijk}|\le A_3=N^{1250}/W^3.
\end{equation}
\end{lemma}

\begin{lemma}[Block signatures at every power]\label{lem:block-signatures}
For $0\le s\le1$, every block factor $F_G^s$ has both normalized
positive-semidefinite tests of~\eqref{eq:signature-normalization}:
$\one\one^{\mathsf T}-Q\succeq0$, for additions and removals.
\end{lemma}

\begin{lemma}[Sparse multipliers]
\label{lem:sparse-multipliers}
For every integer $r\ge2$ there is a constant $D_r\ge1$ such that the
following holds.  Let $F$ be a finite $K_r$-free graph with positive
vertex weights $q_i$ of total mass $s$.  For every
$0<\epsilon\le1/2$, there are jointly distributed random multipliers
$n_i$ satisfying
\begin{equation}
\label{eq:sparse-multipliers}
 0\le n_i\le D_r\epsilon^{-(r-2)},\qquad
 \EE n_i=1,\qquad
 \EE\sum_{iu\in E(F)}q_iq_u n_i n_u\le\epsilon s^2,
\end{equation}
where the edge sum is unordered.
\end{lemma}

\begin{proposition}[One coloring round]\label{prop:one-round}
For all sufficiently large $\Delta$ depending only on $r$, suppose that
a proper partial correspondence coloring and entry weights satisfy
availability, \eqref{eq:weight-bounds}, and
\begin{equation}\label{eq:mass-window}
 K/2\le W_v\le2K\qquad(v\in V(G')).
\end{equation}
There is an extension of the partial coloring and a choice of weights
on the remaining entries that preserve availability and
\eqref{eq:weight-bounds}, and satisfy
\begin{equation}\label{eq:round-conclusions}
 W_v^{\mathrm{new}}\le W_v+\xi,\qquad
 F_v^{\mathrm{new}}\le F_v+\xi,\qquad
 \frac{\deg_{\mathrm{new}}(v)}{\Delta}
 \le(1-\tau)\frac{\deg_{G'}(v)}{\Delta}+\xi
\end{equation}
for every vertex $v$ that remains uncolored.
\end{proposition}

\begin{lemma}[Expected changes]\label{lem:round-expectation}
For the random update just defined,
\begin{equation}\label{eq:round-expectations}
 \begin{aligned}
 \EE\bar W_v&\le W_v+o(\xi),\\
 \EE\bar F_v&\le F_v+\tau(B+1)D_v+o(\xi),\\
 \EE\bar D_{vu}&\ge\tfrac12D_{vu}\qquad(vu\in E(G')).
 \end{aligned}
\end{equation}
\end{lemma}

\begin{lemma}[Bounded input participation]\label{lem:read-concentration}
Let $X_1,\ldots,X_m$ be bounded real functions of finitely many
independent inputs.  Suppose that $X_j$ has range of length at most
$b_j$, and that each input is used by at most $p$ of the functions,
where $p\ge1$ is real.  If $\sum_jb_j^2>0$, then for every $a>0$,
\begin{equation}\label{eq:input-concentration}
 \PP\left(\sum_j(X_j-\EE X_j)\ge a\right),\quad
 \PP\left(\sum_j(X_j-\EE X_j)\le-a\right)
 \ \le\ \exp\left(-\frac{2a^2}{p\sum_jb_j^2}\right).
\end{equation}
If $\sum_jb_j^2=0$, both probabilities are zero.
\end{lemma}

\begin{lemma}[Collision bound]\label{lem:activation-collisions}
Let $\mathcal E_v$ be the set of edges of $H$ with an endpoint hosted
at a neighbor of $v$ in $G'$, and let $X_v$ count the edges of
$\mathcal E_v$ whose two endpoints activate.  Then
\begin{equation}\label{eq:collision-tail}
 \PP\bigl(4K\Delta^{-0.99}X_v>\zeta\bigr)
 \le O(\Delta^3)e^{e-1-\Delta^{0.01}}+e^{-\Delta^{0.8}}.
\end{equation}
For either coefficient family in \eqref{eq:neighbor-coefficients},
the sum of $b_u$ over hosts $u$ counted by $A_u$ that receive no
color is at most $4K\Delta^{-0.99}X_v$.
\end{lemma}

\begin{lemma}
\label{lem:walk-entropy-bound}
With the above definitions,
\begin{equation}
 H_0\ge-\log\ell,\qquad H_R\le O_r(\log\ell).
 \label{eq:walk-entropy-bound}
\end{equation}
\end{lemma}

\begin{proposition}[Supported face codimension]
\label{a:prop-supported-codimension}
For a loopless labelled multigraph on \(n=2m\ge2\) vertices and
\(x\in P(G)\), put \(A=\{e:x_e>0\}\) and \(s_A=|A|\).
Then \(s_A-d(x)\le3m-2\). In particular,
\begin{equation}
\label{a:eq-full-support-codimension}
 s_A-d(x)\le 2(n-2)\quad(n\ge4),
 \qquad s_A-d(x)=1\quad(n=2).
\end{equation}
Hence \(s_A-d(x)\le2n=4m\). For the empty graph,
\(P(G)\) is a singleton in zero coordinates and the codimension is zero.
\end{proposition}

\begin{corollary}[Fractional coordinates]
\label{a:cor-fractional-dimension}
For every \(x\in P(G)\), the integer \(s_f\) is even, and
\begin{equation}
\label{a:eq-fractional-dimension}
 d(x)\ge
 \begin{cases}
 |E_f(x)|-2(s_f-2),&s_f\ge4,\\
 |E_f(x)|-1,&s_f=2,\\
 0,&s_f=0,
 \end{cases}
 \qquad
       \sum_{e\in E_f(x)}x_e=\frac{s_f}{2}.
\end{equation}
\end{corollary}

\begin{corollary}[Separable and nonlinear consequences]\label{cons:legacy-defect}
For every $x\in P(G)$ with $|V(G)|=n=2m>0$,
\begin{align}
 F(x)-4B(x)&\le F(x)-3B(x)\le H(x)\le F(x)+B(x),\label{cons:legacy-separable}\\
 F(x)-H(x)&\le\min\{F(x),3m\}
                  \le8m\bigl(1-e^{-F(x)/m}\bigr).\label{cons:legacy-nonlinear}
\end{align}
Furthermore,
\begin{equation}\label{cons:legacy-bin-gap}
 \ln N(G)\le\max_{x\in P(G)}[F(x)+B(x)]
       \le\ln N(G)+2n
       \le\ln N(G)+\tfrac52n.
\end{equation}
\end{corollary}

\begin{corollary}[Coefficient-three and nonlinear counts]\label{cons:legacy-counts}
A loopless labelled multigraph $G$ on $2m>0$ vertices containing $k\ge1$
pairwise edge-disjoint perfect matchings satisfies
\begin{align}
 N(G)&\ge b_k^m\ge(e^{-3}k)^m,\label{cons:legacy-three-count}\\
 N(G)&\ge\bigl[k\exp\{-8(1-1/k)\}\bigr]^m
                         \ge(e^{-8}k)^m.\label{cons:legacy-eight-count}
\end{align}
The same two conclusions hold when $G$ is $k$-regular and every odd cut
has at least $k$ edges.\label{cons:legacy-regular}
\end{corollary}

\begin{theorem}[Nonlinear entropy bound]
\label{b:thm-nonlinear}
For every \(y\in P(G)\),
\begin{equation}
 F(y)-H(y)\le 8m\bigl(1-e^{-F(y)/m}\bigr).
 \label{b:eq-nonlinear}
\end{equation}
\end{theorem}

\begin{theorem}[Pointwise entropy bounds]\label{ent:main}
Let $G$ be a loopless multigraph on $2m\ge2$ vertices with at least one
perfect matching. For every $x\in P(G)$,
\begin{equation}\label{intro:main-bound}
                  F(x)-\left(2-\frac2m\right)B(x)
                  \le H(x)\le F(x).
\end{equation}
\end{theorem}

\begin{lemma}[Gluing across an odd cut]
\label{geom:lem-gluing}\label{a:lem-tight-cut-gluing}
Suppose $y_i\in P(G_i)$, for $i=1,2$, and their coordinates agree on
$C$. There is a point $y\in P(G)$ with the internal coordinates of the
two $y_i$ and their common crossing coordinates.
\end{lemma}

\begin{theorem}[Perfect matching polytope]
\label{geom:thm-polytope}
For every graph \(G\) as above,
\begin{equation}
\label{geom:eq-polytope}
 P(G)=\left\{x\in\mathbb R^E:
 \begin{aligned}
 x_e&\ge0 &&(e\in E),\\
 x(\delta(v))&=1 &&(v\in V),\\
 x(\delta(S))&\ge1 &&(S\subseteq V,\ |S|\text{ odd})
 \end{aligned}\right\}.
\end{equation}
\end{theorem}

\begin{lemma}[Minimal face and its directions]
\label{geom:lem-face}
For every \(x\in P(G)\), the space \(T(x)\) consists exactly of
the vectors satisfying
\begin{equation}
\label{geom:eq-directions}
\begin{aligned}
 h_e&=0 &&\text{if }x_e=0,\\
 h(\delta(v))&=0 &&(v\in V),\\
 h(\delta(S))&=0
   &&\text{if }|S|\text{ is odd and }x(\delta(S))=1.
\end{aligned}
\end{equation}
Moreover, \(F_x\) is the minimal face containing \(x\), and
\begin{equation}
\label{geom:eq-face-span}
 \operatorname{aff}F_x=x+T(x),\qquad
 F_x=\operatorname{conv}\mathcal A_x,\qquad
 T(x)=\operatorname{span}\{a-x:a\in\mathcal A_x\}.
\end{equation}
The point \(x\) lies in the relative interior of \(F_x\), and every
law on perfect matching vectors with mean \(x\) is supported on
\(\mathcal A_x\).
\end{lemma}

\begin{proposition}[Codimension on positive coordinates]
\label{geom:prop-rank}
Let $|V|=2m\ge2$, and suppose $x\in P(G)$ has $x_e>0$ for every
edge. Then
\begin{equation}
\label{geom:eq-codimension}
 |E|-d(x)\le3m-2.
\end{equation}
\end{proposition}

\begin{lemma}[Fractional coordinates and the minimal face]
\label{geom:lem-reduction}
Let \(x\in P(G)\). The number of vertices in \(V_f(x)\) is even;
write \(|V_f(x)|=2m_f\). Let
\(G_f=(V_f(x),E_f(x))\) and \(\bar x=x|_{E_f(x)}\).
The coordinate extension
\begin{equation}
\label{geom:eq-extension}
 \iota(z)_e=
 \begin{cases}
 z_e,&e\in E_f(x),\\
 x_e,&e\notin E_f(x)
 \end{cases}
\end{equation}
is an affine isomorphism from \(P(G_f)\) onto the face
\[
 Q_x=\{y\in P(G):y_e=x_e\text{ for }e\notin E_f(x)\}.
\]
It sends the minimal face of \(\bar x\) onto \(F_x\). For every
\(z\in P(G_f)\), removing the fixed edges gives a bijection between
laws with mean \(\iota(z)\) and laws on perfect matchings of \(G_f\)
with mean \(z\), preserving their probabilities. Moreover,
\begin{equation}
\label{geom:eq-fractional-rank}
 \sum_{e\in E_f(x)}x_e=m_f,\qquad
 d(x)\ge |E_f(x)|-3m_f+2\quad\text{if }m_f\ge1.
\end{equation}
If \(m_f=0\), then \(x\) is a matching vector and \(d(x)=0\).
\end{lemma}

\begin{lemma}[Continuity at the boundary]\label{ent:continuity}
For a nonempty perfect-matching polytope $P(G)$, the maximum mean entropy
$H$ is attained, nonnegative, concave and continuous on the whole polytope.
\end{lemma}

\begin{lemma}[Exponential laws on the minimal face]\label{ent:exponential}
Every law with mean $x\in P(G)$ is supported on $\mathcal A_x$.
Its entropy maximizer is positive on every atom of $\mathcal A_x$ and has
the form
\begin{equation}\label{ent:gibbs}
 p_a=\frac{e^{\theta\cdot a}}{\sum_{b\in\mathcal A_x}e^{\theta\cdot b}}
 \quad(a\in\mathcal A_x)
\end{equation}
for a finite vector $\theta\in\R^E$.
For every $\eta\in\R^E$, the law obtained by replacing $\theta$ by $\eta$
maximizes entropy at its own mean, and that mean has minimal face $F_x$.
\end{lemma}

\begin{lemma}[Second variation at a fractional maximum]\label{ent:trace}
Let $G$ have $2m\ge2$ vertices, and suppose that $x\in P(G)$ has
$0<x_e<1$ for every edge. If $J_c-H$ has a local maximum at $x$, then,
with $d=\dim F_x$ and $s=|E|$,
\begin{equation}\label{ent:trace-obstruction}
                         0\ge d-s+(c+1)m.
\end{equation}
\end{lemma}

\begin{corollary}[Entropy-dependent defect]
\label{cons:defect}
For every \(x\in P\),
\begin{equation}
 \label{cons:defect-bound}
 0\le F(x)-H(x)
 \le \min\{F(x),\,2m-2\}.
\end{equation}
\end{corollary}

\begin{corollary}[Separable estimates of the matching count]
\label{cons:entropy-count}
One has
\begin{align}
 \ln N&\le\max_{x\in P}F(x)\le\ln N+2m-2,
       \label{cons:F-count}\\
 \ln N&\le\max_{x\in P}H_{\mathrm{bin}}(x)
                         \le\ln N+3m-2.
       \label{cons:binary-count}
\end{align}
\end{corollary}

\begin{theorem}[Many edge-disjoint perfect matchings]
\label{cons:structural}
Let \(G\) be a finite loopless multigraph on \(2m>0\) vertices that
contains \(k\ge1\) pairwise edge-disjoint perfect matchings.
If \(k=1\), then \(N(G)\ge1\). If \(k\ge2\), then
\begin{equation}
 \label{cons:finite-order-count}
 N(G)\ge k^m(1-1/k)^{2(m-1)(k-1)}
       \ge e^{-2(m-1)}k^m
       \ge(e^{-2}k)^m.
\end{equation}
\end{theorem}

\begin{corollary}[Weighted counting estimate]
\label{cons:weighted}
For every finite real vector \(\beta\),
\begin{equation}
 \label{cons:weighted-bracket}
                q^*-\frac{2m-2}{\ln2}
                \le\log_2 Z_\beta\le q^*.
\end{equation}
\end{corollary}

\begin{corollary}[Conservative weighted bracket]
\label{d:coarse-weighted}
For every finite loopless labelled multigraph on an even number
\(n\ge2\) of vertices with at least one perfect matching, and every
finite real vector \(\beta\in\mathbb R^E\),
\begin{equation}
 \label{d:eq-coarse-weighted}
 q^*-4n\le\log_2 Z_\beta\le q^*+n.
\end{equation}
\end{corollary}

\begin{lemma}[Weighted completion]
\label{d:lem-penalized-count}
The contribution of matchings using an absent pair satisfies
\[
  0\le Z_{\mathrm{bad}}\le2^{-20n}.
\]
Moreover,
\begin{equation}
\label{d:eq-penalized-count}
\begin{aligned}
 N=0&\quad\Longrightarrow\quad \log_2 Z_\beta\le-20n,\\
 N>0&\quad\Longrightarrow\quad
       \max\{1,2^{-n/2}N\}\le Z_\beta\le2N.
\end{aligned}
\end{equation}
\end{lemma}

\begin{lemma}[Dyadic entropy approximation]
\label{d:lem-dyadic-entropy}
The function \(\psi\) is concave, with integer slopes of absolute value
at most \(K\).  For every \(x\in P\),
\begin{equation}
\label{d:eq-dyadic-entropy-error}
  0\le h_2(x)-\sum_e\psi(x_e)
     \le\frac n2+1\le n.
\end{equation}
\end{lemma}

\begin{lemma}[Finite projected ascent]
\label{d:lem-projected-ascent}
Let \(N_{\mathrm{it}}=pD_0\), set \(x^{(0)}=0\), and for
\(j=0,\ldots,N_{\mathrm{it}}-1\) choose a supergradient
\(g^{(j)}\) as in Lemma~\ref{d:lem-exact-penalty} and set
\begin{equation}
\label{d:eq-projected-iterations}
x^{(j+1)}
=\Pi_{[0,1]^p}\left(x^{(j)}+\frac{g^{(j)}}{D_0}\right),
\end{equation}
where \(\Pi_{[0,1]^p}\) clips each coordinate to \([0,1]\).
Then
\begin{equation}
\label{d:eq-optimization-accuracy}
R=\left\lfloor\max_{0\le j<N_{\mathrm{it}}}\Phi(x^{(j)})\right\rfloor
\qquad\text{satisfies}\qquad
R\le f^*\le R+2.
\end{equation}
\end{lemma}

\begin{proposition}[Bit complexity]
\label{d:prop-bit-complexity}
The algorithm above is uniform and deterministic, and its running time
and output length are polynomial in the input bit length.
\end{proposition}

\begin{proposition}[Sharp codimension and prescribed-marginal entropy]
\label{ex:prop-klee-face}
For every integer \(m\ge1\), the graph \(G_m\) and the point
\(x^{(m)}\) above satisfy
\[
 F_{x^{(m)}}=
 \operatorname{conv}\{a(M_1),a(M_2),a(M_3)\},
 \qquad d(x^{(m)})=2.
\]
The unique law on perfect matchings with mean \(x^{(m)}\) is the
uniform law on \(M_1,M_2,M_3\). Consequently,
\begin{equation}
\label{ex:eq-klee-values}
 \begin{aligned}
 |E(G_m)|-d(x^{(m)})&=3m-2,\\
 H(x^{(m)})&=\ln3,\\
 F(x^{(m)})&=m\ln3,\\
 B(x^{(m)})&=2m\ln(3/2).
 \end{aligned}
\end{equation}
\end{proposition}

\begin{theorem}[Fourier smoothing of matrix squares]
\label{thm:fourier-smoothing}
Let $t,r\ge1$ be integers.  For each $1\le i\le t$, let $X_i$ and
$\mathcal M_i$ be nonempty finite sets with uniform probability, and
let $Y_i$ be a specified copy of $(\mathbb F_2)^a$, where $a\ge1$ and
$L=2^a$.  For $m\in\mathcal M_i$ and $y\in Y_i$, let
$\pi_{i,y}^m$ be a probability distribution on $X_i$.
Suppose that, for some $\theta\ge0$, these distributions satisfy
\begin{equation}\label{eq:channel-marginal}
  \E_{m\in\mathcal M_i}\pi_{i,y}^m(x)=\frac1{|X_i|}
  \qquad(x\in X_i, y\in Y_i)
\end{equation}
and, for every real function $g:X_i\to\R$ and every $y\in Y_i$,
\begin{equation}\label{eq:channel-variance}
  \E_{m\in\mathcal M_i}
  \left(\sum_{x\in X_i}\pi_{i,y}^m(x)g(x)-\E_{x\in X_i}g(x)\right)^2
  \le\theta\E_{x\in X_i}g(x)^2.
\end{equation}
Let $F:\prod_iX_i\to\mathbb S_+^r$ satisfy $\tr F(x)\le B$ for all
$x$, where $B>0$ and $\mathbb S_+^r$ is the cone of real symmetric
positive semidefinite $r$-by-$r$ matrices.  Fix $\lambda>1$ such that
\begin{equation}\label{eq:smoothing-parameter}
  L\lambda^2C_L\theta\le1,
\end{equation}
where $C_L=2^{L-1}$ is the constant of Lemma~\ref{lem:splitting}.
For $m=(m_1,\ldots,m_t)\in\prod_i\mathcal M_i$, define
\begin{equation}\label{eq:product-average}
  \overline F_m(y)
  =\sum_{x\in\prod_iX_i}
     \left(\prod_{i=1}^t\pi_{i,y_i}^{m_i}(x_i)\right)F(x).
\end{equation}

There is a finite integer $R$ and a family of functions
$H_q^m:\prod_iY_i\to\R^{R\times r}$, indexed by
$m\in\prod_i\mathcal M_i$ and $q\in\Lambda^t$, such that
\begin{equation}\label{eq:smoothing-squares}
  \overline F_m(y)=\sum_{q\in\Lambda^t}H_q^m(y)^{\mathsf T}H_q^m(y).
\end{equation}
For each $m,q$, form the horizontal concatenation and its Gram matrix
\begin{equation}\label{eq:smoothing-gram}
  U_q^m=
    \left[\lambda^{\operatorname{dist}(q,p)/2}
           \widehat H_{q,p}^m\right]_{p\in\Lambda^t},
  \qquad C_q^m=U_q^m(U_q^m)^{\mathsf T},
\end{equation}
where $\widehat H_{q,p}^m$ is the Fourier coefficient of $H_q^m$ at $p$.
The family can be chosen so that, for independent uniform $m_i$,
\begin{equation}\label{eq:smoothing-potential}
  \E_m\sum_{q\in\Lambda^t}\normF{C_q^m}^2\le2^tB^2.
\end{equation}
Consequently, at least one $m$ satisfies
\begin{equation}\label{eq:smoothing-coefficients}
  \sum_{q,p\in\Lambda^t}
    \lambda^{\operatorname{dist}(q,p)}\normF{\widehat H_{q,p}^m}^2
  \le L^t\sqrt r\,B\,2^{t/2}.
\end{equation}
\end{theorem}

\begin{theorem}\label{thm:main}
There is a constant $c>0$ such that, for every fixed $0<\rho<1$,
there is $n_0=n_0(\rho)$ for which
\[
 \rankpsd A_n(\rho)\ge2^{cn}
\]
for every even $n\ge n_0$.
\end{theorem}

\begin{lemma}[Local averaging]
\label{lem:local-averaging}
For each fixed even $d\ge2$, there are $k_0(d)$ and numbers
$\theta_d(k)\ge0$, defined for even $k\ge k_0(d)$, with
$\theta_d(k)\to0$ as $k\to\infty$, such that the following holds for the
construction above, for both $b\in\{0,1\}$ and every $y\in Y_b$.
First,
\begin{equation}
  \E_m\pi_y^m(a)=\frac1{|X|}\qquad(a\in X).
  \label{local:marginal}
\end{equation}
Second, every real function $B:X\to\R$ satisfies
\begin{equation}
  \E_m\left|(T_yB)(m)-\E_aB(a)\right|^2
  \le\theta_d(k)\,
      \E_a\left|B(a)-\E_aB(a)\right|^2.
  \label{local:scalar-variance}
\end{equation}
For every pair of positive integers $p,q$, the same constant gives, for
every $B:X\to\R^{p\times q}$,
\begin{equation}
  \E_m\normF{(T_yB)(m)-\E_aB(a)}^2
  \le\theta_d(k)\,
      \E_a\normF{B(a)-\E_aB(a)}^2
  \le\theta_d(k)\,\E_a\normF{B(a)}^2.
  \label{local:matrix-variance}
\end{equation}
One may take $\theta_d(k)=O_d(k^{-1/4}\sqrt{\log(k+2)})$.
\end{lemma}

\begin{theorem}[Uniform smoothing]\label{thm:matching-smoothing}
For every fixed \(\ell\ge1\) and \(K>0\), there are an integer
\(d\ge1\) and \(N_0\) such that, for every even \(N\ge N_0\), every
positive integer cell-size vector summing to \(N\), and every admissible table,
\begin{equation}\label{smooth:eq-smoothing}
  \normop{T_t(I-\Pi_d)}\le N^{-K}.
\end{equation}
Moreover, for each fixed partition \(Z\) and function \(f\), the values
\((T_t\Pi_df)(Z)\), as \(t\) varies over all admissible tables, are
given by a single polynomial of total degree at most \(d\) in the
intercell counts \((t_{uv})_{u<v}\).
\end{theorem}

\begin{lemma}\label{smooth:lem-fourth-moment}
Put \(a_\ell=\ell(\ell+1)+1\) and
\(b_\ell=2a_\ell+\ell^2\).  For every admissible table,
\begin{equation}\label{smooth:eq-fourth-moment}
  \tr\bigl((T_t^*T_t)^2\bigr)
  \le e^{2a_\ell}(N+1)^{b_\ell}.
\end{equation}
\end{lemma}

\begin{lemma}[Expanding multigraphs]
  \label{lem:expander}
  For every sufficiently large even integer \(t\), there is a bipartite
  \(d\)-regular multigraph \(H\) on \([t]\) such that
  \begin{equation}
    |\delta_H(W)|\geq \beta d\min\{|W|,t-|W|\}
    \qquad (W\subseteq[t]).
    \label{eq:parity-expansion}
  \end{equation}
  In particular, \(H\) is connected.
\end{lemma}

\begin{lemma}[Orthogonal splitting]\label{lem:splitting}
Let $A_1,\ldots,A_L$ be real symmetric positive semidefinite matrices
on a finite-dimensional Euclidean space.  There are mutually orthogonal
projections $P_1,\ldots,P_L$ such that $\sum_{s=1}^L P_s=I$ and
\begin{equation}\label{eq:orthogonal-splitting}
  \sum_{z=1}^L\sum_{s\ne z}\normF{P_sA_zP_s}^{2}
  \le C_L\sum_{z\ne z'}\tr(A_zA_{z'}),
  \qquad C_L=2^{L-1}.
\end{equation}
The sum on the right is over ordered pairs of distinct indices.
Zero projections are allowed.
\end{lemma}

\begin{lemma}[Order-uniform rank bound]\label{lem:all-orders}
For each realization of all coins and every permutation $\pi$,
\begin{equation}\label{eq:all-orders}
 N_{\ge h}(\pi)\ge\lambda_h.
\end{equation}
\end{lemma}

\begin{lemma}[Telescoping rank cost]\label{lem:rank-cost}
For each listed group $h$, the nominal statistic $z_h$ satisfies
\begin{equation}\label{eq:rank-cost}
 \sum_b\rk(S_{h,b}\mid\widehat F(b-2)+K_{h,b})\ge z_h-c_h,
 \qquad
 c_h=|C_h|+\sum_{j>h}\bigl(|C_j|+|D_j|/\kappa\bigr).
\end{equation}
\end{lemma}

\begin{lemma}[Independent test thinning]\label{lem:thinning}
For a listed group $h$, let $\mathcal F_{-h}$ be generated by $H,D,C$,
the parity $\varepsilon$, and all test-mask memberships outside $G_h$.
Then
\begin{equation}\label{eq:test-thinning}
 \Ex[\lambda_h\mid\mathcal F_{-h}]
 \ge t\sum_b\rk(S_{h,b}\mid\widehat F(b-2)+K_{h,b})
 \ge t(z_h-c_h).
\end{equation}
\end{lemma}

\begin{lemma}[Candidate mass]\label{lem:filter}
The set $Y$ is independent, $Y\subseteq U$, and
\begin{equation}\label{eq:candidate-mass}
 \Ex_H u(Y)=W/2,\qquad \Ex_H u(U)\le W.
\end{equation}
\end{lemma}

\begin{lemma}[Density expansion]\label{lem:density}
The largest maximizer in \eqref{eq:density-objective} exists, the map $Q_h$
is increasing, and $P\subseteq Q_h(P)$. If $Q=Q_h(P)$, then for every set $Z$,
\begin{equation}\label{eq:density-residual}
 |D_h\cap(\cl(Q+Z)\setminus Q)|\le\kappa\rk(Z\mid Q).
\end{equation}
\end{lemma}

\begin{lemma}[Path properties]\label{lem:paths}
The paths increase with $k$ and satisfy
\begin{equation}\label{eq:path-inclusions}
 F_{h-1}(k)\subseteq X_h(k)\subseteq F_h(k)\subseteq X_h(k+1).
\end{equation}
They equal $E$ for $k\ge0$. Moreover $X_h(k)=L$ for $k<a_h$ and
$F_h(k)=L$ for $k<a_h-1$. If $e$ is a nonloop, its nominal birth
\[
 b_h(e)=\min\{k:e\in X_h(k)\}
\]
is either $a_h$, with $e\in Q_h(L)$, or belongs to $[a_h+2,0]$.
\end{lemma}

\begin{lemma}[Feasibility and measurability]\label{lem:feasibility}
The main rule maintains an independent accepted set at every arrival
prefix, for every permutation. It is a measurable rule based only on the
allowed information.
\end{lemma}

\begin{lemma}[A generator budget for the entire path]\label{lem:generators}
For each listed group $h$ there is a set $J_h\subseteq D_h$ and increasing
subsets $J_h(k)\subseteq J_h$ such that
\begin{equation}\label{eq:generator-budget}
 X_h(k)=\cl(F_{h-1}(k)+J_h(k)),\qquad
 |J_h|\le |D_h|/\kappa.
\end{equation}
In particular $\rk(Q_h(L))\le |D_h|/\kappa$.
\end{lemma}

\begin{lemma}[Exit mass]\label{lem:exit}
Every nonloop $d$ exits its $h$-th nominal path by the end of the reverse
computation, and
\begin{equation}\label{eq:low-exit-hazard}
 \Prob(\text{$d$ exits at a step with }p_{b-1}<\eta\mid H,D)<\tfrac12.
\end{equation}
Consequently,
\begin{equation}\label{eq:squared-exit-mass}
 \sum_{b=a_h}^{0}
  \Ex\bigl[\ind{d\in X_h(b)}p_{b-1}^{2}\mid H,D\bigr]
       \ge\frac{\eta}{2}.
\end{equation}
\end{lemma}

\begin{lemma}[Safe sampled labels]\label{lem:safe}
For every listed group $h$,
\begin{equation}\label{eq:safe-samples}
 \Ex[\sigma_h\mid H,D]
   \ge\frac{\eta}{4}|D_h\cap Y|-\frac{|D_h|}{\kappa}.
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:hidden}
There is a measurable rule in the fixed-vector formulation that is feasible for every
realization and every permutation, and for every $w\in[0,\infty)^E$ satisfies
\begin{equation}\label{eq:hidden-guarantee}
 \Ex_R\left[\min_{\pi}\sum_{e\in A(w,R,\pi)}w_e\right]
 \ge 2^{-293}\OPT_M(w).
\end{equation}
Its revealed mask is selected before any weights are seen.
\end{proposition}

\begin{lemma}[One-sample simulation]\label{lem:simulation}
A measurable fixed-vector rule satisfying \eqref{eq:hidden-guarantee} yields
a measurable one-sample rule with the same competitive ratio against the
adversary of Theorem~\ref{thm:main}.
\end{lemma}

\begin{lemma}[Sample-to-rank transfer]\label{lem:transfer}
Fix $H$.  For a true group $U_i$, define $z_i=z_h$ and
$\sigma_i=\sigma_h$ if the group is listed with index $h$, and set
both quantities to zero if it is unlisted.  If $n_i\ge\kappa$, then
\begin{equation}\label{eq:rank-transfer}
 \Ex[z_i\mid H]
 \ge\frac{\gamma|Y_i|-2^{-23}n_i}{\kappa},
 \qquad \gamma=\frac\eta{16}=2^{-16}.
\end{equation}
\end{lemma}

\begin{theorem}[Logical hole bound]
\label{thm:logical-hole-bound}
Let $\lambda$ be balanced, let $B$ be its bottleneck similarity, and set
\[
 D_0=10^8(n+1)^4.
\]
For every even set $U\subseteq V$,
\begin{equation}
\label{eq:logical-hole-bound}
 g_\lambda(U)\Phi_B(U)\le 2D_0^{|U|/2}.
\end{equation}
\end{theorem}

\begin{lemma}[Four-hole inequality]
\label{lem:four-holes}
For any positive activities $\mu$ and four distinct vertices $a,b,c,d$,
\[
 g_\mu(abcd)\le
 g_\mu(ab)g_\mu(cd)+g_\mu(ac)g_\mu(bd)
                         +g_\mu(ad)g_\mu(bc).
\]
Consequently, if every row maximum is at most $4$, then
\begin{equation}
\label{eq:small-hole-bounds}
 g_\mu(\varnothing)=1,\qquad
 g_\mu(U)\le4\quad(|U|=2),\qquad
 g_\mu(U)\le48\quad(|U|=4).
\end{equation}
\end{lemma}

\begin{lemma}[Relocating a hole along a strong path]
\label{lem:hole-relocation}
Let $B$ be defined by \eqref{eq:bottleneck}, and suppose that
$\mu_e\ge\lambda_e$ for every edge and
\[
 \frac18\le r_i(\mu)\le4\qquad(i\in V).
\]
If $|U|\in\{2,4\}$ and $i,j\in U$ are distinct, then
\begin{equation}
\label{eq:hole-relocation-bound}
 g_\mu(U)\le\frac{10^5n}{B_{ij}}.
\end{equation}
\end{lemma}

\begin{proposition}[Marked matching laws]\label{prop:marked-laws}
For arbitrary positive logical activities, sample from the bag matching
law and reveal the edge portions as above. The all-real event has
probability $1/I$;
conditional on this event, the decoded logical matching has law
$\pi_\lambda$. For each logical edge $uv$,
\begin{equation}\label{eq:probe}
 \Prb(\text{probe for }uv\text{ is used and all other edges are real})
 =\frac{g_\lambda(uv)}{DI}.
\end{equation}
Conditional on this event, the residual logical matching has the
$\lambda$-weighted perfect-matching law on the vertices other than
$u,v$.
\end{proposition}

\begin{proposition}[Bounded inflation]\label{prop:bag-inflation}
If the logical activities are balanced, then
\begin{equation}\label{eq:inflation}
 1\le I\le2.
\end{equation}
\end{proposition}

\begin{lemma}\label{lem:deletion-accounting}
If an even hole set $U$ has a real completion, then $R$ is even,
$|R|\le|U|$, and
\begin{equation}\label{eq:deletion-identity}
 Z'(-U)
 =C_0 F(U)
 Z_\lambda\bigl(-R;E_{\mathrm{br}}(U)\text{ forbidden}\bigr).
\end{equation}
In particular,
$g'(U)\le F(U)g_\lambda(R)$.
\end{lemma}

\begin{lemma}[Pairings in a hierarchy]
\label{lem:ultrametric-pairing}
Let $B\ge1$ be a symmetric similarity on a finite vertex set $X$,
satisfying $B_{ij}\ge\min\{B_{ik},B_{kj}\}$. Let $\mathcal C_t$ be
the equivalence classes of $B\ge t$, including singletons.
For every even set $U\subseteq X$,
\begin{equation}
\label{eq:threshold-pairing}
 \log\Phi_B(U)
 =\int_1^\infty\sum_{C\in\mathcal C_t}
       \left\lfloor\frac{|C\cap U|}{2}\right\rfloor\frac{dt}{t}.
\end{equation}
There is one pairing that attains the maximum number of internal pairs
in every threshold class simultaneously.
\end{lemma}

\begin{lemma}\label{lem:lifted-hole-bound}
If the logical activities are balanced, then for every even set
$U$ of enlarged vertices,
\[
 g'(U)\Phi_{B'}(U)\le2D_0^{|U|/2}.
\]
More precisely, for every $U$ with a real completion, the deterministic
quantities above satisfy
\begin{equation}\label{eq:threshold-charge}
 F(U)\Phi_{B'}(U)\le\Phi_B(R).
\end{equation}
\end{lemma}

\begin{theorem}[Pair energy inequality]
\label{thm:pair-energy}
For every two real functions $f_1,f_2$ on $\calM$,
\begin{equation}
\label{eq:pair-energy}
 \Var_\pi f_1\le L\,
 \calE\bigl((A,B)\mapsto f_1(A)+f_2(B)\bigr).
\end{equation}
The same constant works for every common-interval clamp of the
reference activities.
\end{theorem}

\begin{lemma}[Elementary energy bounds]
\label{lem:elementary-pair-energy}
With the notation above,
\begin{align}
 \sum_A\pi(A)\sum_{A'\in\mathcal S(A)}
       (f_1(A)-f_1(A'))^2
 &\le60N^2A_0^2 E,
 \label{eq:safe-switch-energy}\\
 \sum_A\pi(A)\sum_{A'\in\mathcal K(A)}
       (f_1(A)-f_1(A'))^2
 &\le12NA_0 E,
 \label{eq:color-energy}\\
 \sum_{A,B}\pi(A)\pi(B)\sum_{C\in\mathcal C(A,B)}
       \bigl(F(A,B)-F((A,B)^C)\bigr)^2
 &\le6NE.
 \label{eq:cycle-energy}
\end{align}
Here $\mathcal C(A,B)$ denotes the discrepancy cycles, and $(A,B)^C$
is the pair after swapping $C$.
\end{lemma}

\begin{lemma}[Cell identity and cancellation]
\label{lem:cell-identity}
The quantities just defined satisfy
\begin{equation}
\label{eq:single-cell-identity}
 D_C=\Delta+\sum_{J\in P}g_J-\sum_{J\in Q}g_J+E_P-E_Q
\end{equation}
for each cell.  Consequently,
\begin{equation}
\label{eq:global-cell-identity}
 D_C=\sum_{\text{cells of }C}(\Delta+E_P-E_Q).
\end{equation}
\end{lemma}

\begin{lemma}[Swap sum]
\label{lem:swap-sum}
The sum in \eqref{eq:swap-sum} satisfies $\Sigma_{\rm swap}\le12N^2E$.
\end{lemma}

\begin{lemma}\label{lem:replica-gap}
The lazy product chain has spectral gap at least $3/(8M)$, and hence
at least $1/(20LM)$. The dependence on $L$ in the stronger bound
is carried by $q=32L$, and hence by $M$.
\end{lemma}

\begin{lemma}\label{lem:one-pass-scaling}
Suppose $G$ is symmetric and $\alpha\le G_{ij}\le3$ for $i\ne j$.
Initialize $v_i=2$ for every vertex and visit the vertices in their
fixed order, setting
\begin{equation}\label{eq:scale-update}
 v_i\leftarrow\max_{j\ne i}\frac{G_{ij}}{v_j}.
\end{equation}
Every coordinate only decreases, all final coordinates lie in
$[\alpha/2,2]$, and the final vector satisfies
$v_i v_j\ge G_{ij}$ with an equality in every row.
\end{lemma}

\begin{lemma}\label{lem:successful-stage}
Suppose the current logical activities are balanced and every empirical
mean is within $\sigma$ of its exact mean. Then the next scaled
activities are balanced and
\begin{equation}\label{eq:stage-relative-error}
 \left|\frac{\widehat R}{R}-1\right|
 \le10\sigma\le\frac\eps{100K}.
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:maximum-degree}
For every integer $r\ge4$, every real number $\Delta\ge3$, and every finite $K_r$-free graph $G$
with $n$ vertices and maximum degree at most $\Delta$,
\[
 \alpha(G)\ge \frac{F_G^*}{D_r\log\Delta}
 \qquad\text{and}\qquad
 \alpha(G)\ge \frac{n\log\Delta}{4D_r\Delta}.
\]
\end{proposition}

\begin{lemma}[Shared rejection sampling]\label{lem:shared-rejection}
Let $I$ and $J$ be finite nonempty sets, and let $(p_i)_{i\in I}$ be
probability distributions on $J$. There are jointly distributed random
variables $(Y_i)_{i\in I}$ such that $Y_i$ has law $p_i$ and, for every
$i,i'\in I$,
\[
 \mathbb P(Y_i\ne Y_{i'})
 \le \frac{2\|p_i-p_{i'}\|_{\mathrm{TV}}}
 {1+\|p_i-p_{i'}\|_{\mathrm{TV}}}
 \le 2\|p_i-p_{i'}\|_{\mathrm{TV}}.
\]
The resulting joint law has finite support.
\end{lemma}

\begin{lemma}\label{lem:reverse-admissibility}
The probability that $Y_{u,v}$ is inadmissible, averaged over
$(u,v)\sim\mu$, is at most
\begin{equation}\label{eq:inadmissibility-bound}
 \delta_x:=\frac{(A_C+1)\log x}{\sqrt x+\log x}.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:weighted-splitting}
There is a choice of these labels for which the projection
$(u,y)\mapsto u$ preserves weights, maps directed edges injectively
to directed edges of $H$, and satisfies
\begin{align}
 \max_{a\in V(H')}w(N_{H'}(a))&\le e^{\sqrt x},
 \label{eq:split-neighborhood}\\
 T_{H'}(w)&\ge(1-a_C\log x/\sqrt x)T_H(w),
 \label{eq:split-triangles}
\end{align}
where $a_C=6(B_C+A_C+1)$.
\end{lemma}

\begin{proposition}\label{prop:neighborhood-reduction}
Let $G$ be a finite positive-vertex-weighted graph satisfying the
cross-mass condition~\eqref{eq:cross-mass} with constant $C\ge1$, and suppose that
$\max_vw(N_G(v))\le e^x$ for some $x>X(C)$. There is a finite
positive-vertex-weighted graph $G'$ with a weight-preserving map to
$G$ that is injective on directed edges, such that
\begin{align}
 \max_vw(N_{G'}(v))&\le e^{\sqrt x},\label{eq:step-neighborhood}\\
 T_{G'}(w)&\ge
 \left(1-a_C\frac{\log x}{\sqrt x}\right)T_G(w)
       -\frac{M_G(w)}x.\label{eq:step-triangles}
\end{align}
It also satisfies the same cross-mass condition, and $M_{G'}(w)\le M_G(w)$.
\end{proposition}

\begin{lemma}[Smoothing the local walks]
\label{lem:entropy-smoothing}
Under \eqref{eq:cross-mass} and \eqref{eq:walk-hypotheses}, put
\[
 E_C=42C^2+2C,\qquad A_C=10+E_C,\qquad B_C=2\sqrt{A_C+1},
 \qquad R=\lceil x\rceil.
\]
Each $K_u^j$ is reversible with stationary measure $\pi_u$, and
\begin{equation}
 K_u^j(v,y)\le xw_y\qquad(j\ge0).
 \label{eq:walk-density}
\end{equation}
Moreover,
\begin{equation}
 -\log x\le H_0\le H_1\le\cdots\le H_R\le A_C\log x.
 \label{eq:entropy-upper}
\end{equation}
There exists $j\in\{0,\ldots,R-1\}$ such that, under the ordered triangle
law,
\begin{equation}
 \mathbb E\bigl\|K_u^j(v,\cdot)-K_u^j(z,\cdot)\bigr\|_{\mathrm{TV}}
 \le B_C\sqrt{\frac{\log x}{x}}.
 \label{eq:triangle-row-distance}
\end{equation}
\end{lemma}

\begin{lemma}[Preservation under splitting]
\label{lem:invariant-preservation}
Let $(G,w)$ satisfy \eqref{eq:cross-mass} with constant $C$.
Let $H$ be a finite simple graph and let $\pi:V(H)\to V(G)$ satisfy
the following conditions:
\begin{enumerate}
 \item every edge $\{a,b\}$ of $H$ maps to the edge
       $\{\pi(a),\pi(b)\}$ of $G$;
 \item the map $(a,b)\mapsto(\pi(a),\pi(b))$ is injective on
       directed edges of $H$.
\end{enumerate}
Give each $a\in V(H)$ the weight $\widetilde w_a=w_{\pi(a)}$.
Then $(H,\widetilde w)$ satisfies
\eqref{eq:cross-mass} with the same constant $C$.  Moreover,
\begin{gather*}
 M_H(\widetilde w)\le M_G(w),\qquad
 T_H(\widetilde w)\le T_G(w),\\
 \widetilde w(N_H(a))\le w(N_G(\pi(a)))
 \quad\text{for every }a\in V(H).
\end{gather*}
These conclusions are preserved under any finite composition of such maps.
\end{lemma}

\begin{lemma}\label{lem:optimizer}
For every nonempty finite simple graph $G$, the function $F_G$ attains its
maximum.  Every maximizer $w$ has positive coordinates and satisfies
\begin{equation}\label{eq:stationarity}
 \log(1/w_v)=w(N_G(v)) \qquad(v\in V(G)).
\end{equation}
In particular, $w_v\le1$.  For every nonnegative vector $q$,
\begin{equation}\label{eq:optimizer-divergence}
 0\le F_G(w)-F_G(q)
 =\sum_v\left(q_v\log\frac{q_v}{w_v}-q_v+w_v\right)
   +M_G(q-w).
\end{equation}
Here a term with $q_v=0$ in the sum equals $w_v$.
\end{lemma}

\begin{lemma}\label{lem:sparse-multipliers}
Let $r\ge2$ be an integer, let $G$ be a finite $K_r$-free graph with positive vertex
weights $w$, and put $s=w(V(G))$.  For every $0<\varepsilon\le1/2$ there
are jointly distributed random variables $(m_v)_{v\in V(G)}$ such that
\begin{equation}\label{eq:sparse-multipliers}
 0\le m_v\le b_r(\varepsilon)
 :=2^{r(r-2)}\varepsilon^{-(r-2)},\qquad
 \mathbb E m_v=1,\qquad
 \mathbb E M_G((w_vm_v)_v)\le\varepsilon s^2.
\end{equation}
Their joint distribution can be taken to have finite support.
\end{lemma}

\begin{lemma}\label{lem:cross-mass}
Let $r\ge2$ be an integer and let $w$ maximize $F_G$ on a nonempty finite $K_r$-free
graph $G$.  For every $x\ge1$ and all vertex sets $S,D$ with
$w(S),w(D)\le e^x$,
\begin{equation}\label{eq:optimizer-cross-mass}
 e_w(S,D)\le C_r g_x(w(S)),
 \qquad C_r=16r^2.
\end{equation}
The sets $S$ and $D$ need not be disjoint.
\end{lemma}

\begin{lemma}\label{lem:hole-triangle-free}
The hole relation is symmetric, has no loops, and is triangle-free.
\end{lemma}

\begin{lemma}\label{lem:cut-kernel}
The intersection of \(W_l\) over any strict majority of tags is \(W_*\).
Two representations of the same cut profile differ by a constant tuple with value in \(W_*\).
\end{lemma}

\begin{theorem}[Raw supersaturation]\label{thm:raw-supersaturation}
For the construction parameters specified in \Cref{sec:geometry,sec:parameters}, for all sufficiently large \(n\), every probability law \(\sigma\) on units satisfying
\begin{equation}\label{eq:raw-law-caps}
 \sigma_1\le M\mu,\qquad \sigma_2\le M\mu,\qquad
 \sigma\le 2^{DN}\mu^2
\end{equation}
has the following property: two independent units drawn from \(\sigma\) have all four cross holes with probability at least \(2^{-100gN}\).
The inequalities in \Cref{eq:raw-law-caps} are pointwise inequalities of measures on the finite raw spaces.
\end{theorem}

\begin{lemma}[Gram normalization]\label{lem:gram-frame-normalization}
Let \(p,q\) be nonnegative integers with \(p+q\le N\).
For \(p\) independent uniform plus vectors and \(q\) independent uniform minus vectors in paired copies of \(\F^N\), and a prescribed \(p\)-by-\(q\) Gram matrix \(G\), the probability of that Gram matrix together with individual injectivity of both frames is at most \(2^{-pq}\) and at least
\begin{equation}\label{eq:bounded-gram-normalization}
 2^{-pq}(1-2^{p-N})(1-2^{p+q-N}).
\end{equation}
In particular, any consistent Gram specification on a bounded number of vectors, together with injectivity on each side, has probability bounded below by a positive constant for large \(N\).
\end{lemma}

\begin{lemma}[Two peelings]\label{lem:peeling}
Take the constants in \Cref{eq:pin-budgets,eq:law-budgets}, and choose the reference accuracy in \Cref{eq:reference-image-cap} with \(\epsilon<\zeta/4\).
For every law \(\sigma\) satisfying \Cref{eq:raw-law-caps}, the following decompositions are available.
\begin{enumerate}[label=\textup{(\alph*)}]
\item
After discarding the exception in \Cref{lem:raw-intersections} and at most \(2^{-\zeta N}\) further mass, the law is partitioned into \emph{leaves}.
Each leaf has fixed pin spaces with total dimension at most \(K_1\), and its normalized law \(\sigma_\lambda\) satisfies
\begin{equation}\label{eq:leaf-minentropy}
 \sigma_\lambda\{\text{a specified exact-image constraint of rank }t
                 \text{ modulo the pins}\}
 \le 2^{-(1-\zeta)tN}
 \qquad(t\ge1).
\end{equation}
The normalized leaf laws satisfy a common bound \(2^{O(N)}\mu^2\), with the implied constant determined by the early parameters.

\item
Suppose a restriction of the mixed law has relative mass \(2^{-o(N)}\).
One may discard an exponentially small fraction of that restricted law so that every remaining normalized leaf restriction satisfies
\begin{equation}\label{eq:final-leaf-minentropy}
 \sigma_\lambda\{\text{a specified exact-image constraint of rank }t
                 \text{ modulo the pins}\}
 \le 2^{-(1-2\zeta)tN}
 \qquad(t\ge1),
\end{equation}
and still has density \(2^{O(N)}\) relative to \(\mu^2\).
For several successive restrictions, the same statement applies to their combined relative cost.

\item
In addition, suppose at most \(u_0\) further coefficient directions per unit must be pinned, their coefficient choices and all required scalar metadata having at most \(2^{O(n)}\) possibilities per old leaf.
After splitting by these choices and their exact images, discarding exponentially small mass, and peeling again, the total pin dimension is at most \(K\).
The fresh leaves satisfy \Cref{eq:leaf-minentropy}; after further restrictions as in \textup{(b)}, they satisfy \Cref{eq:final-leaf-minentropy}.
They retain a uniform \(2^{O(N)}\mu^2\) density bound.
\end{enumerate}
In all parts the mixed law uses each leaf's actual mass, normalized only after the indicated discards.
No equal reweighting of leaves is used.
After a restriction, \(\sigma_\lambda\) denotes the normalized surviving
law on that leaf.
\end{lemma}

\begin{lemma}[Label support]\label{lem:label-support}
Every $w\in W$ of rank at most $R_*$ has a representation
\begin{equation}\label{eq:label-decomposition}
 w=\sum_{s\in L}(p_s\otimes I)Z_s(p_s\otimes I)\trans,
 \qquad |L|\le R_*,
\end{equation}
where each $Z_s$ is symmetric, $(Z_s)_{ii}=(Z_s)_{0i}$, and
$\sum_{s\in L}\rank Z_s\le R_*$.
\end{lemma}

\begin{lemma}\label{lem:sparse-pin-labels}
Put $L_0^{\rm lab}=R_*+14$.  At an endpoint, the union of the
nonzero label supports of all vectors in all $S_{i,e}^{\pm}$
that can be written as
$\sum_{s\in L}p_s\otimes z_s$ with $|L|\le L_0^{\rm lab}$
has size at most
\begin{equation}\label{eq:label-budget}
 B_0=2|\cE|K(R_*+14).
\end{equation}
\end{lemma}

\begin{lemma}[Rank growth without a cover]
\label{lem:no-cover-rank}
Let \(r\ge1\) be an integer, set \(m_r=100r+10\) and
\(q_r=2^{-m_r}\), and let \(s\) be a power of two with
\(s\ge2^{m_r}\).  Suppose \(T_1,\ldots,T_s\) are independent copies
of a random tensor of total component rank at most \(r\).
If every fixed componentwise cover with dimension at most \(rs\)
in each mode has probability less than \(p\), then
\begin{equation}
 \PP\left\{\rank\left(\sum_{j=1}^sT_j\right)<q_rs/4\right\}
 \le 4^s p^{q_rs/2}.
 \label{eq:no-cover-rank}
\end{equation}
Here rank means the sum of component ranks.
\end{lemma}

\begin{lemma}[Exactification of vanishing prediction classes]
\label{lem:empty-status}
If \(e_1=e_2=0\), deleting \(o(1)\) unit mass makes
\begin{equation}
 p_i=T(\lambda_i,\cdot)+a
 \quad\text{on all of }\cX,\qquad i=1,2,
 \label{eq:exact-prediction}
\end{equation}
an exact identity on every retained unit.
\end{lemma}

\begin{lemma}[Equal coefficients when the tensor difference vanishes]
\label{lem:zero-delta}
On a predicted branch with \(\Delta=0\) throughout,
\(\alpha_1=\alpha_2\).
\end{lemma}

\begin{lemma}[Finite twisted regularity]
\label{lem:product-twisted-regularity}
Let $\abs{W}\le B$ on the product key space of $I\cup J$, and let
$\delta>0$. There is a decomposition
\begin{equation}\label{eq:twisted-regularity-decomposition}
 W=\sum_{a=1}^{L'}c_a f_a(k_I)g_a(k_J)\tau_a(k_I,k_J)+D,
\end{equation}
where $\abs{f_a},\abs{g_a}\le1$, $\tau_a\in\mathcal T_{I,J}$,
$\abs{c_a}\le B$, $\norm{D}_\infty\le2B$, and
$\norm{D}_{\square,\mathcal T}\le\delta$. The number $L'$ is bounded
in terms of $B,\delta$ and the twist count only. The functions $f_a,g_a$
may be chosen as indicators of cells in finite group partitions.
\end{lemma}

\begin{lemma}[A terminal remainder on actual inputs]
\label{lem:product-terminal-remainder}
Let $I,J$ be a nontrivial partition of some of the template positions.
Let $D_n$ be a common function of their global keys with
$\norm{D_n}_\infty\le B_1$ and
$\norm{D_n}_{\square,\mathcal T}\le\delta$. Let $\psi_n(I,J)$
be any product of the specified nominal $L,R$ signs and global Gram
signs crossing from $I$ to $J$, evaluated on their actual inputs and
keys. For each fixed $\rho>0$, except on exponentially small mixed
mass,
\begin{equation}\label{eq:product-remainder-actual}
 \sup_{\abs{f},\abs{g}\le1}
 \abs{\E_{z_I,z_J}D_n(K_I,K_J)\psi_n(I,J)f(O,z_I)g(O,z_J)}
 \le\bigl(C_3\delta+\rho+o(1)\bigr)^{1/4}.
\end{equation}
The constant $C_3$ and the vanishing error depend only on $B_1$ and
the fixed template. The weights may depend arbitrarily on the fixed
orientation. The exceptional set does not depend on those weights.
\end{lemma}

\begin{corollary}[Factorized integration of the approximant]
\label{cor:weak-product-factorized-integration}
For the structured sum in \eqref{eq:weak-product-approximant} and
arbitrary bounded unary input weights, outside exponentially small
mixed mass,
\begin{align}\label{eq:weak-product-factorized-integration}
 &\E_z\mathcal A_n(O,z)S_n(K(O,z))\prod_jw_j(O,z_j)\notag\\
 &\qquad=
 \kappa\sum_{a=1}^{L}c_{a,n}
       \prod_j\E_{z_j}
        \bigl[f_{a,j,n}(K_j(O,z_j))w_j(O,z_j)\bigr]+o(1).
\end{align}
The error is uniform over the unary weights. An orientation-only
filter may be included before averaging this identity over leaves.
\end{corollary}

\begin{lemma}[Successful-query density]
\label{lem:limit-density}
For almost every $Z$, the full limiting successful-query measure on
this side has density
\begin{equation}
\label{eq:limit-density}
G_Z(u)=\kappa\int
  \prod_{\ell}h^\theta_{t_\ell,\upsilon_\ell}
                    \bigl(\xi_\ell(u)\bigr)\,d\alpha_Z(\theta)
\qquad (u\in\Upsilon)
\end{equation}
with respect to $\rho$.
\end{lemma}

\begin{proposition}[The limiting overlap obstruction]
\label{prop:limit-overlap}
Assume \eqref{eq:limit-vanishing-overlap}. In the common experiment of
\Cref{lem:limit-model}, almost every sampled pair of orientation records
has the following property: there is no usable numerical option whose
two orientation flags pass and for which, at every matched position,
\begin{equation}
\label{eq:limit-positive-generator}
\int_{\Xi_{l,q}}
 h^{\theta_A}_{t_A,\upsilon_A}(\xi)
 h^{\theta_B}_{t_B,\upsilon_B}(\xi)\,dm_{l,q}(\xi)>0.
\end{equation}
\end{proposition}

\begin{lemma}[Dual relations]
\label{lem:status-duality}
Any obstruction to the scalar system has a nonzero vector of weights
$(s_1,s_2,r_1,r_2)\in\F^4$. On every edge span $V_{ij}$ these give
a relation
\begin{equation}
\label{eq:status-dual-relation}
s_j(p_{A,i}+h_{A,i})+r_i(p_{B,j}+h_{B,j})
=\mathbf c_{ij}\cdot\mathbf x_{A,i}
 +\mathbf c'_{ij}\cdot\mathbf x_{B,j}
 +\beta_{ij}(h_{A,i}+h_{B,j})+\gamma_{ij}q
\end{equation}
for suitable coefficients. The scalar system is soluble if, for every
such relation, the sum of the right sides evaluated at the local targets
is zero.
\end{lemma}

\begin{lemma}[Extraction of a global prediction]
\label{lem:status-global-prediction}
On the no-prediction alternative of \Cref{prop:status-preparation}, the
probability that the iid base arrays are obstructable is less than $.1$.
\end{lemma}

\begin{lemma}[Predicted scalar compatibility]
\label{lem:status-predicted}
For a predicted pair with a table satisfying the compatibility
conditions of \Cref{prop:status-preparation}, the system
\eqref{eq:status-local-targets}--\eqref{eq:status-coupled-targets}
is soluble. The assertion survives any further bounded label
exclusions leaving generic labels.
\end{lemma}

\begin{lemma}[Uniform large-set hit estimate]
\label{lem:rare-large-set-hit}
Fix \(\delta>0\), and consider a sequence of unit laws whose mixed
joint densities are at most \(2^{O(N)}\) relative to \(\mu^2\), whose
two marginals are at most \(M2^{o(N)}\mu\), and whose marked effective
spaces have the rank and dimension bounds of \Cref{lem:unary-positivity}.
The implied joint-density constant is uniform.
Set
\begin{equation}
 c_{\mathrm{hit}}(\delta)
   =\frac14\,\kappa_{\min}\beta^{s_{\max}}\delta.
 \label{eq:rare-hit-threshold}
\end{equation}
For every fixed \(p>0\),
\begin{equation}
 \sup_{\mathfrak r,W_n}
 \PP\!\left(
 \begin{array}{l}
 \mathfrak r\text{ is feasible at }\omega,\\
 Q_{\omega,\mathfrak r}(W_n)<c_{\mathrm{hit}}(\delta)
 \end{array}\right)
 =o(n^{-p}),
 \label{eq:rare-superpolynomial-tail}
\end{equation}
where the supremum is over the finitely many numerical requests
and deterministic measurable sets
\(W_n\subseteq\cK_{\mathfrak r,n}\) satisfying
\(\nu_{\mathfrak r,n}(W_n)\ge\delta\).
Each choice of \(W_n\) has its own exceptional orientations.
\end{lemma}

\begin{proposition}
\label{prop:rare-overlap}
In the inverse-polynomial alternative of
\Cref{prop:status-preparation}, the overlap criterion
\eqref{eq:overlap-criterion} holds with a lower bound
\(\Omega(N^{-4})\), along the prepared sequence.
\end{proposition}
